"""Патч: наблюдатель trend_resume (только тень) в robot_loop.py + новые файлы.

Что делает
  • создаёт services/trend_resume.py, tests/test_trend_resume.py, scripts/trend_resume_report.py
    (существующие файлы НЕ перезаписывает);
  • robot_loop.py: импорт, self.trend_resume, observe() на каждом скане ДО фильтров,
    plan["trend_resume"] рядом с plan["trend_trigger"].
Торговлю не меняет: observe/snapshot не бросают исключений и ничего не блокируют.

Запуск из корня репозитория: python scripts/patch_trend_resume.py
Идемпотентен; делает .bak-before-trend-resume; UTF-8; переводы строк сохраняются.
"""
import sys
from pathlib import Path

ROOT = Path(sys.argv[1]) if len(sys.argv) > 1 else Path(".")
LOOP = ROOT / "apps/api/workers/robot_loop.py"
NEW = {'apps/api/services/trend_resume.py': '"""Событие «возобновление тренда» — наблюдение в тени (#trend-resume-2026-10-23).\n\nЗачем\n-----\nТрендовый кандидат — СОСТОЯНИЕ (`price < EMA20 < EMA50` на 4h и 1h), оно держится\nчасами и днями и не говорит, где цена внутри движения. Вход идёт «по цене очередного\nскана». Вечер 22–23.10: пять шортов подряд, ни один не вышел в заметную прибыль\n(макс. прибыль 0.0–0.5% при стопе 1.0–1.6%), все получили стоп при развороте.\n`trend_trigger` смотрит только расстояние до EMA20 и это не объясняет исход (замер\nпо 300 сделкам). Не хватает именно СОБЫТИЯ: откат к опоре и возобновление.\n\nЧто делает модуль\n-----------------\nТолько НАБЛЮДАЕТ. На каждом скане запоминает по символу, где цена относительно EMA20\nстаршего ТФ (по умолчанию 1h) в ATR, и по запросу отдаёт снимок для записи в план\nсделки. Вход он НЕ меняет, ничего не блокирует, любая ошибка → пустой снимок.\n\nОпределения (ЗАМОРОЖЕНЫ до просмотра результатов, не подбираются)\n  d      = (EMA20 − цена)/ATR для шорта, (цена − EMA20)/ATR для лонга: «насколько\n           цена ушла ОТ опоры в сторону сделки» (как в trend_trigger.extension_in_atr).\n  touched = за последние WINDOW минут был хотя бы один замер с d <= 0\n           (цена касалась EMA20 или заходила за неё против сделки).\n  resumed = touched И сейчас d > 0 (цена вернулась на сторону сделки).\nПервичная метрика — `resumed`. Остальные поля (d_now, d_min_win, minutes_since_touch)\nпишутся для разведочного анализа; решение по ним принимать нельзя.\n\nОграничение: история в памяти процесса. После рестарта/деплоя она пустая, поэтому\nснимок содержит `observed_min` и `history_complete`; в анализ берутся только записи\nс полной историей. Свечи между сканами не хранятся — это замер по скану (~раз в минуту).\n"""\nfrom __future__ import annotations\n\nimport time\nfrom collections import deque\n\nfrom core.config import settings\n\n\ndef _value(ctx, key):\n    if ctx is None:\n        return None\n    if isinstance(ctx, dict):\n        return ctx.get(key)\n    return getattr(ctx, key, None)\n\n\ndef _signed_ext(ctx, side: str):\n    """(EMA20 − цена)/ATR для шорта, (цена − EMA20)/ATR для лонга. None — нельзя."""\n    try:\n        last = float(_value(ctx, "last_close"))\n        ema20 = float(_value(ctx, "ema20"))\n        atr = float(_value(ctx, "atr14"))\n    except (TypeError, ValueError):\n        return None\n    if atr <= 0:\n        return None\n    delta = last - ema20 if str(side).lower() in ("long", "buy") else ema20 - last\n    return delta / atr\n\n\nclass TrendResumeTracker:\n    def __init__(self, *, now=time.time):\n        self._now = now\n        self._hist: dict[tuple[str, str], deque] = {}\n        self._first: dict[str, float] = {}\n\n    # ── настройки (читаются при каждом вызове, перезапуск не нужен) ──────────\n    @staticmethod\n    def _enabled() -> bool:\n        return bool(getattr(settings, "TREND_RESUME_ENABLED", True))\n\n    @staticmethod\n    def _tf() -> str:\n        return str(getattr(settings, "TREND_RESUME_TF", "1h"))\n\n    @staticmethod\n    def _window_sec() -> float:\n        return float(getattr(settings, "TREND_RESUME_WINDOW_MIN", 360.0)) * 60.0\n\n    def observe(self, symbol: str, contexts) -> None:\n        """Запомнить положение цены для обеих сторон. Никогда не бросает."""\n        try:\n            if not self._enabled() or not isinstance(contexts, dict):\n                return\n            ctx = contexts.get(self._tf())\n            if ctx is None:\n                return\n            t = float(self._now())\n            self._first.setdefault(symbol, t)\n            horizon = t - self._window_sec()\n            for side in ("long", "short"):\n                d = _signed_ext(ctx, side)\n                if d is None:\n                    continue\n                q = self._hist.setdefault((symbol, side), deque())\n                # не чаще раза в 30 с: скан раз в ~минуту, лишние точки не нужны\n                if q and t - q[-1][0] < 30.0:\n                    q[-1] = (q[-1][0], d)\n                else:\n                    q.append((t, d))\n                while q and q[0][0] < horizon:\n                    q.popleft()\n        except Exception:  # noqa: BLE001 — наблюдатель не должен ронять цикл\n            return\n\n    def snapshot(self, symbol: str, side: str) -> dict:\n        """Снимок для plan_json.trend_resume. Всегда dict, никогда не бросает."""\n        try:\n            if not self._enabled():\n                return {"enabled": False}\n            s = "long" if str(side).lower() in ("long", "buy") else "short"\n            q = self._hist.get((symbol, s))\n            if not q:\n                return {"enabled": True, "side": s, "tf": self._tf(), "samples": 0,\n                        "history_complete": False, "resumed": None}\n            t = float(self._now())\n            window = self._window_sec()\n            vals = [d for _, d in q]\n            d_now = vals[-1]\n            touched_at = next((ts for ts, d in reversed(q) if d <= 0.0), None)\n            touched = touched_at is not None\n            observed = max(0.0, t - self._first.get(symbol, t))\n            return {\n                "enabled": True,\n                "side": s,\n                "tf": self._tf(),\n                "window_min": round(window / 60.0, 1),\n                "samples": len(vals),\n                "d_now": round(d_now, 4),\n                "d_min_win": round(min(vals), 4),\n                "d_max_win": round(max(vals), 4),\n                "touched": touched,\n                "minutes_since_touch": (round((t - touched_at) / 60.0, 1)\n                                        if touched_at is not None else None),\n                "resumed": bool(touched and d_now > 0.0),\n                "observed_min": round(observed / 60.0, 1),\n                # полная история: символ наблюдается не меньше окна (с запасом 10%)\n                "history_complete": observed >= window * 0.9,\n            }\n        except Exception:  # noqa: BLE001\n            return {"enabled": True, "error": True}\n', 'apps/api/tests/test_trend_resume.py': '"""Тесты наблюдателя trend_resume: только считает, не влияет на вход."""\nfrom services.trend_resume import TrendResumeTracker\n\n\nclass Clock:\n    def __init__(self):\n        self.t = 1_000_000.0\n\n    def __call__(self):\n        return self.t\n\n\ndef ctx(last, ema=100.0, atr=1.0):\n    return {"1h": {"last_close": last, "ema20": ema, "atr14": atr}}\n\n\ndef test_short_pullback_then_resume_is_resumed():\n    c = Clock(); tr = TrendResumeTracker(now=c)\n    for price in (97.0, 99.0, 100.5, 99.5, 98.5):   # ниже EMA, коснулись, вернулись\n        tr.observe("BTC/USDT", ctx(price)); c.t += 600\n    s = tr.snapshot("BTC/USDT", "short")\n    assert s["touched"] is True and s["resumed"] is True\n    assert s["d_now"] > 0 and s["d_min_win"] < 0\n\n\ndef test_short_never_touched_is_not_resumed():\n    c = Clock(); tr = TrendResumeTracker(now=c)\n    for price in (97.0, 96.5, 96.0):\n        tr.observe("ETH/USDT", ctx(price)); c.t += 600\n    s = tr.snapshot("ETH/USDT", "short")\n    assert s["touched"] is False and s["resumed"] is False\n    assert s["minutes_since_touch"] is None\n\n\ndef test_still_on_wrong_side_is_not_resumed():\n    c = Clock(); tr = TrendResumeTracker(now=c)\n    for price in (97.0, 100.5, 101.0):               # коснулись и ещё не вернулись\n        tr.observe("SOL/USDT", ctx(price)); c.t += 600\n    assert tr.snapshot("SOL/USDT", "short")["resumed"] is False\n\n\ndef test_long_is_mirrored():\n    c = Clock(); tr = TrendResumeTracker(now=c)\n    for price in (103.0, 100.0, 101.5):\n        tr.observe("LTC/USDT", ctx(price)); c.t += 600\n    assert tr.snapshot("LTC/USDT", "long")["resumed"] is True\n\n\ndef test_old_touch_leaves_window():\n    c = Clock(); tr = TrendResumeTracker(now=c)\n    tr.observe("XRP/USDT", ctx(100.5)); c.t += 8 * 3600   # касание старше окна 6 ч\n    tr.observe("XRP/USDT", ctx(97.0))\n    s = tr.snapshot("XRP/USDT", "short")\n    assert s["touched"] is False and s["resumed"] is False\n\n\ndef test_history_complete_only_after_window():\n    c = Clock(); tr = TrendResumeTracker(now=c)\n    tr.observe("DOGE/USDT", ctx(97.0)); c.t += 3600\n    tr.observe("DOGE/USDT", ctx(97.0))\n    assert tr.snapshot("DOGE/USDT", "short")["history_complete"] is False\n    c.t += 6 * 3600\n    tr.observe("DOGE/USDT", ctx(97.0))\n    assert tr.snapshot("DOGE/USDT", "short")["history_complete"] is True\n\n\ndef test_fail_safe_on_garbage():\n    tr = TrendResumeTracker()\n    tr.observe("X", None)\n    tr.observe("X", {"1h": {"last_close": "n/a"}})\n    tr.observe("X", {"1h": {"last_close": 1, "ema20": 1, "atr14": 0}})\n    assert tr.snapshot("X", "short")["resumed"] is None\n\n\ndef test_unknown_symbol_snapshot_is_safe():\n    s = TrendResumeTracker().snapshot("NEW/USDT", "short")\n    assert s["samples"] == 0 and s["history_complete"] is False\n', 'scripts/trend_resume_report.py': '"""Отчёт по наблюдению trend_resume: входы «с возобновлением» против «без».\n\nКритерий РЕШЕНИЯ зафиксирован заранее (23.10.2026), по новым сделкам, не по истории:\n  • сделки trade_mode=trend, у которых в plan.trend_resume history_complete=true;\n  • всего >= 100 и в каждой группе (resumed / не resumed) >= 25;\n  • нижняя граница 95% блочного ДИ разницы среднего net (resumed − не resumed) > 0.\nТолько тогда обсуждаем превращение события в условие входа. Иначе — не превращаем.\n\nЗапуск (из корня репозитория), нужны ОБА файла выгрузки:\n  python scripts\\\\trend_resume_report.py signals.json storage\\\\ml\\\\trade_outcomes.jsonl\nsignals.json — выгрузка /signals ({"items": [...]}) или список; plan внутри каждого сигнала.\n"""\nimport json, random, statistics as st, sys\n\nif len(sys.argv) < 3:\n    sys.exit(__doc__)\nraw = json.load(open(sys.argv[1], encoding="utf-8"))\nitems = raw["items"] if isinstance(raw, dict) else raw\nplan = {int(x["id"]): (x.get("plan") or {}) for x in items if str(x.get("id", "")).isdigit()}\nrows = [json.loads(l) for l in open(sys.argv[2], encoding="utf-8") if l.strip()]\n\n\ndef net(x):\n    t = x.get("total_net_pnl")\n    return (x.get("closed_net_pnl") if t is None else t) or 0.0\n\n\ndata = []\nfor x in sorted(rows, key=lambda r: str(r.get("opened_at", ""))):\n    if x.get("trade_mode") != "trend":\n        continue\n    try:\n        tr = plan.get(int(x["signal_id"]), {}).get("trend_resume")\n    except (TypeError, ValueError):\n        continue\n    if isinstance(tr, dict):\n        data.append((tr, net(x), x))\n\nseen = sum(1 for tr, _, _ in data if tr.get("samples"))\nfull = [(tr, n, x) for tr, n, x in data if tr.get("history_complete") and tr.get("resumed") is not None]\nprint(f"трендовых сделок с полем trend_resume: {len(data)}; с замерами: {seen}; с полной историей: {len(full)}")\nA = [n for tr, n, _ in full if tr["resumed"]]\nB = [n for tr, n, _ in full if not tr["resumed"]]\nprint(f"resumed: n={len(A)} среднее net={st.mean(A):+.2f}" if A else "resumed: нет данных")\nprint(f"не resumed: n={len(B)} среднее net={st.mean(B):+.2f}" if B else "не resumed: нет данных")\nif len(A) < 2 or len(B) < 2:\n    sys.exit("Недостаточно данных для сравнения.")\n\nnets = [n for _, n, _ in full]\nflags = [bool(tr["resumed"]) for tr, _, _ in full]\ndiff = st.mean(A) - st.mean(B)\nrnd = random.Random(42)\nblk = 20\nbs = []\nfor _ in range(2000):\n    idx = []\n    while len(idx) < len(nets):\n        s0 = rnd.randrange(0, len(nets))\n        idx.extend(range(s0, min(s0 + blk, len(nets))))\n    idx = idx[: len(nets)]\n    a = [nets[i] for i in idx if flags[i]]\n    b = [nets[i] for i in idx if not flags[i]]\n    if a and b:\n        bs.append(st.mean(a) - st.mean(b))\nbs.sort()\nlo, hi = bs[int(0.025 * len(bs))], bs[int(0.975 * len(bs)) - 1]\nprint(f"разница (resumed − нет): {diff:+.2f} USDT/сделку, CI95 [{lo:+.2f}; {hi:+.2f}]")\nok = len(full) >= 100 and len(A) >= 25 and len(B) >= 25 and lo > 0\nif len(full) < 100 or len(A) < 25 or len(B) < 25:\n    print("РЕШЕНИЕ: рано (нужно >=100 всего и >=25 в каждой группе).")\nelse:\n    print("РЕШЕНИЕ:", "критерий выполнен — можно обсуждать условие входа." if ok else "критерий НЕ выполнен — событие условием входа не делаем.")\n'}


def once(text, old, new, label):
    n = text.count(old)
    if n != 1:
        sys.exit(f"[{label}] якорь найден {n} раз(а), ожидался 1 - robot_loop.py не менялся")
    return text.replace(old, new)


for rel, content in NEW.items():
    p = ROOT / rel
    if p.exists():
        print(f"{rel}: уже есть, пропускаю")
        continue
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(content.encode("utf-8"))
    print(f"{rel}: создан")

raw = LOOP.read_bytes().decode("utf-8")
crlf = "\r\n" in raw
t = raw.replace("\r\n", "\n")
if "trend_resume" in t:
    print("robot_loop: уже применено")
else:
    t = once(t, "from services import trend_trigger, tz_entry_shadow, tp_reachability, momentum_gate\n",
             "from services import trend_trigger, tz_entry_shadow, tp_reachability, momentum_gate\n"
             "from services.trend_resume import TrendResumeTracker\n", "import")
    t = once(t, "        self.impulse_latch = ImpulseLatch()\n",
             "        self.impulse_latch = ImpulseLatch()\n"
             "        # (#trend-resume-2026-10-23) Наблюдатель «откат к EMA20 1h и возобновление».\n"
             "        # Только тень: пишет снимок в plan, вход не меняет. История в памяти.\n"
             "        self.trend_resume = TrendResumeTracker()\n", "init")
    t = once(t, "            if result.action == \"hold\":\n                _scan_skips[symbol] = f\"hold:",
             "            # (#trend-resume-2026-10-23) Положение цены относительно EMA20 1h запоминается\n"
             "            # на КАЖДОМ скане, в том числе при hold: иначе в истории будут дыры.\n"
             "            self.trend_resume.observe(symbol, getattr(result, \"timeframes\", None))\n\n"
             "            if result.action == \"hold\":\n                _scan_skips[symbol] = f\"hold:", "observe")
    t = once(t, "                    \"trend_trigger\": _trigger.as_dict(),\n",
             "                    \"trend_trigger\": _trigger.as_dict(),\n"
             "                    # (#trend-resume-2026-10-23) Тень: было ли возобновление после отката.\n"
             "                    \"trend_resume\": self.trend_resume.snapshot(symbol, result.action),\n", "plan")
    LOOP.with_name(LOOP.name + ".bak-before-trend-resume").write_bytes(raw.encode("utf-8"))
    LOOP.write_bytes((t.replace("\n", "\r\n") if crlf else t).encode("utf-8"))
    print("robot_loop: ok")
